import sqlite3, itertools, sys, json

sys.path.append('/root/.codex/skills/civ6lib')
from scripts import placement_rules as pr
from scripts import hex_utils
sys.modules['hex_utils'] = hex_utils
sys.modules['placement_rules'] = pr
from scripts import adjacency_rules as ar

map_path='/data/maps/e2e_test_case_0.Civ6Map'
conn=sqlite3.connect(map_path)
cur=conn.cursor()
cur.execute('SELECT Width, Height FROM Map WHERE ID="Default"')
width, height = cur.fetchone()
cur.execute('SELECT ID, TerrainType FROM Plots')
terrain_by_id = {row[0]: row[1] for row in cur.fetchall()}
cur.execute('SELECT ID, FeatureType FROM PlotFeatures')
feature_by_id = {row[0]: row[1] for row in cur.fetchall()}
cur.execute('SELECT ID, ResourceType FROM PlotResources')
resource_by_id = {row[0]: row[1] for row in cur.fetchall()}
cur.execute('SELECT ID, ImprovementType FROM PlotImprovements')
improvement_by_id = {row[0]: row[1] for row in cur.fetchall()}
cur.execute('SELECT ID, IsNEOfRiver, IsWOfRiver, IsNWOfRiver FROM PlotRivers')
river_edges_by_id = {}
for rid, ne, w, nw in cur.fetchall():
    edges = []
    if ne: edges.append(1)
    if nw: edges.append(2)
    if w: edges.append(3)
    river_edges_by_id[rid] = edges
conn.close()

def terrain_to_base(terrain_type):
    if terrain_type is None:
        return None
    if 'MOUNTAIN' in terrain_type:
        return 'MOUNTAIN'
    if terrain_type.endswith('OCEAN'):
        return 'OCEAN'
    if terrain_type.endswith('COAST'):
        return 'COAST'
    if terrain_type.endswith('LAKE'):
        return 'LAKE'
    if terrain_type.endswith('GRASS'):
        return 'GRASS'
    if terrain_type.endswith('PLAINS'):
        return 'PLAINS'
    if terrain_type.endswith('DESERT'):
        return 'DESERT'
    if terrain_type.endswith('TUNDRA'):
        return 'TUNDRA'
    if terrain_type.endswith('SNOW'):
        return 'SNOW'
    if 'GRASS' in terrain_type:
        return 'GRASS'
    if 'PLAINS' in terrain_type:
        return 'PLAINS'
    return terrain_type

# Build tiles

tiles = {}
for plot_id in range(width*height):
    x = plot_id % width
    y = plot_id // width
    terrain = terrain_by_id.get(plot_id)
    feature = feature_by_id.get(plot_id)
    resource = resource_by_id.get(plot_id)
    improvement = improvement_by_id.get(plot_id)
    base_terrain = terrain_to_base(terrain)
    is_hills = False
    is_floodplains = feature is not None and 'FLOODPLAINS' in feature
    river_edges = river_edges_by_id.get(plot_id, [])
    tiles[(x,y)] = pr.Tile(
        x=x,
        y=y,
        terrain=base_terrain,
        feature=feature,
        is_hills=is_hills,
        is_floodplains=is_floodplains,
        river_edges=list(river_edges),
        river_names=[],
        resource=resource,
        resource_type=None,
        improvement=improvement,
    )

# city center placement rules

def valid_city_center(coord):
    tile = tiles.get(coord)
    if tile is None:
        return False
    if tile.is_water:
        return False
    if tile.is_mountain:
        return False
    if tile.is_natural_wonder:
        return False
    return True

population = 9
max_specialty = pr.calculate_max_specialty_districts(population)

adjacency_districts = [
    pr.DistrictType.CAMPUS,
    pr.DistrictType.HOLY_SITE,
    pr.DistrictType.THEATER_SQUARE,
    pr.DistrictType.COMMERCIAL_HUB,
    pr.DistrictType.HARBOR,
    pr.DistrictType.INDUSTRIAL_ZONE,
    pr.DistrictType.GOVERNMENT_PLAZA,
]

land_tiles = [coord for coord in tiles if valid_city_center(coord)]
calc = ar.AdjacencyCalculator(tiles)

best = None
best_details = None

for city_center in land_tiles:
    rules = pr.get_placement_rules(tiles, city_center, population)

    # tiles within range 3
    range_tiles = [coord for coord in tiles if pr.hex_distance(city_center[0], city_center[1], coord[0], coord[1]) <= 3]

    candidates = {}
    for dt in adjacency_districts:
        valid_tiles = []
        for coord in range_tiles:
            if coord == city_center:
                continue
            res = rules.validate_placement(dt, coord[0], coord[1], {city_center: pr.DistrictType.CITY_CENTER})
            if res.valid:
                valid_tiles.append(coord)
        if valid_tiles:
            candidates[dt] = valid_tiles

    available_types = [dt for dt in adjacency_districts if dt in candidates]
    if len(available_types) < max_specialty:
        continue

    for district_types in itertools.combinations(available_types, max_specialty):
        district_types = list(district_types)
        district_types.sort(key=lambda d: len(candidates[d]))

        def search(i, placements_dict):
            global best, best_details
            if i == len(district_types):
                placements = {city_center: pr.DistrictType.CITY_CENTER}
                placements.update(placements_dict)
                total, per = calc.calculate_total_adjacency(placements)
                total_adj = sum(per.get(coord, 0) for coord in placements_dict)
                if best is None or total_adj > best:
                    best = total_adj
                    best_details = {
                        'city_center': city_center,
                        'placements': placements_dict.copy(),
                        'per': {coord: per.get(coord,0) for coord in placements_dict}
                    }
                return
            dt = district_types[i]
            for coord in candidates[dt]:
                if coord in placements_dict or coord == city_center:
                    continue
                res = rules.validate_placement(dt, coord[0], coord[1], {**{city_center: pr.DistrictType.CITY_CENTER}, **placements_dict})
                if not res.valid:
                    continue
                placements_dict[coord] = dt
                search(i+1, placements_dict)
                placements_dict.pop(coord)
        search(0, {})

print('best', best)
print('details', best_details)
