import sqlite3
map_path='/data/maps/e2e_test_case_0.Civ6Map'
conn=sqlite3.connect(map_path)
cur=conn.cursor()
cur.execute('SELECT Width, Height FROM Map WHERE ID="Default"')
width, height = cur.fetchone()
cur.execute('SELECT ID, TerrainType FROM Plots')
terrain_by_id = {row[0]: row[1] for row in cur.fetchall()}
cur.execute('SELECT ID, FeatureType FROM PlotFeatures')
feature_by_id = {row[0]: row[1] for row in cur.fetchall()}
cur.execute('SELECT ID, IsNEOfRiver, IsWOfRiver, IsNWOfRiver FROM PlotRivers')
river_ids = {row[0] for row in cur.fetchall()}
conn.close()

# area of interest
x0,x1=18,26
y0,y1=10,18

# legend: 
# M mountain, G grass, P plains, C coast, O ocean
# F forest, J jungle, R reef, H fissure, L floodplains, V river tile
# We'll show feature char uppercase if present

for y in range(y0,y1+1):
    row=''
    for x in range(x0,x1+1):
        pid = y*width + x
        terrain = terrain_by_id.get(pid)
        feat = feature_by_id.get(pid)
        base = '.'
        if terrain:
            if 'MOUNTAIN' in terrain:
                base='M'
            elif terrain.endswith('GRASS'):
                base='g'
            elif terrain.endswith('PLAINS'):
                base='p'
            elif terrain.endswith('COAST'):
                base='c'
            elif terrain.endswith('OCEAN'):
                base='o'
        # overlay feature
        if feat == 'FEATURE_FOREST':
            base='F'
        elif feat == 'FEATURE_JUNGLE':
            base='J'
        elif feat == 'FEATURE_GEOTHERMAL_FISSURE':
            base='H'
        elif feat == 'FEATURE_REEF':
            base='R'
        elif feat and 'FLOODPLAINS' in feat:
            base='L'
        # mark river
        if pid in river_ids:
            # lowercase to mark river
            base = base.lower()
        row += f'{base:>2}'
    print(f'y={y:02d} {row}')
